<section class="record-form" id="issue"><div class="gw-panel-head"><h2>Issue Equipment</h2><span>Assign an available registered asset.</span></div><form method="post"><input type="hidden" name="action" value="issue_asset"><div class="form-grid"><div><label>Asset</label><select name="asset_id" required><option value="">Select available asset</option><?php foreach($assets as $a): if(($a['status']??'')==='Available' && (int)$a['available_quantity']>0):?><option value="<?=$a['id']?>"><?=e($a['asset_tag'].' — '.$a['name'])?> (<?=e($a['available_quantity'])?> available)</option><?php endif; endforeach;?></select></div><div><label>Employee</label><input name="employee_name" required></div><div><label>Issued Date</label><input type="date" name="issued_date" required value="<?=date('Y-m-d')?>"></div><div><label>Expected Return</label><input type="date" name="expected_return"></div><div class="full"><label>Notes</label><textarea name="notes"></textarea></div></div><div class="record-actions"><button class="gw-btn primary">Issue Equipment</button></div></form></section>
<section class="gw-panel" id="available-items" style="margin-top:20px"><div class="gw-panel-head"><h2>Available Items</h2><span>Current asset availability</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Picture</th><th>Name</th><th>Serial No.</th><th>Units Available</th><th>Status</th><th>Picture Action</th></tr></thead><tbody><?php foreach($assets as $a): $available=(int)($a['available_quantity']??0); ?><tr>
<td><?php if(!empty($a['image_data'])): ?><button type="button" class="asset-picture-thumb" onclick="showAssetPicture(<?= (int)$a['id'] ?>, <?=json_encode((string)$a['name'],JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_HEX_AMP)?>)" title="View asset picture"><img src="<?=e(url('/modules/asset_equipment/asset_image.php?id='.(int)$a['id']))?>" alt="<?=e($a['name'])?>"></button><?php else: ?><span class="asset-picture-placeholder">No picture</span><?php endif; ?></td>
<td><?=e($a['name'])?></td><td><?=e($a['serial_number']??'—')?></td><td><?=e($available)?></td><td><?=e($a['status']??'—')?></td>
<td><form method="post" enctype="multipart/form-data" class="asset-picture-form"><input type="hidden" name="action" value="update_asset_picture"><input type="hidden" name="asset_id" value="<?= (int)$a['id'] ?>"><label class="gw-btn ghost asset-picture-upload"> <?=!empty($a['image_data'])?'Change':'Add'?> Picture<input type="file" name="asset_image" accept="image/jpeg,image/png,image/webp,image/gif" onchange="this.form.submit()" hidden></label></form></td>
</tr><?php endforeach;if(!$assets):?><tr><td colspan="6" class="empty">No items available.</td></tr><?php endif;?></tbody></table></div></section>
