<script>
function showAssetPicture(assetId, assetName){
 const root=document.getElementById('modalRoot'); if(!root)return;
 const src=<?=json_encode(url('/modules/asset_equipment/asset_image.php'))?>+'?id='+encodeURIComponent(String(assetId));
 root.innerHTML='<div class="gw-modal-backdrop" onclick="if(event.target===this)closeModal()"><div class="gw-modal" style="width:min(900px,100%)"><div class="gw-modal-head"><div><strong>'+escapeHtml(assetName||'Asset Picture')+'</strong><small>Asset / equipment picture</small></div><button class="gw-modal-close" onclick="closeModal()">×</button></div><div class="gw-modal-body" style="text-align:center"><img src="'+src+'" alt="'+escapeHtml(assetName||'Asset Picture')+'" style="max-width:100%;max-height:70vh;object-fit:contain;border-radius:12px"></div></div></div>';
}
</script>
